INSERT INTO task_type (code, name, metric) VALUES ('det', 'Object detection', 'mAP@0.5:0.95') ON CONFLICT (code) DO NOTHING;
INSERT INTO task_step (task_type_id, position, text) SELECT id, 1, 'Collect images and define the class list' FROM task_type WHERE code = 'det' ON CONFLICT DO NOTHING;
INSERT INTO task_step (task_type_id, position, text) SELECT id, 2, 'Annotate bounding boxes in YOLO format' FROM task_type WHERE code = 'det' ON CONFLICT DO NOTHING;
INSERT INTO task_step (task_type_id, position, text) SELECT id, 3, 'Train a YOLO baseline, then tune image size and augmentation' FROM task_type WHERE code = 'det' ON CONFLICT DO NOTHING;
INSERT INTO task_step (task_type_id, position, text) SELECT id, 4, 'Evaluate mAP and review per-class false positives' FROM task_type WHERE code = 'det' ON CONFLICT DO NOTHING;
INSERT INTO task_step (task_type_id, position, text) SELECT id, 5, 'Export the model and run it on video or behind an API' FROM task_type WHERE code = 'det' ON CONFLICT DO NOTHING;
INSERT INTO task_type (code, name, metric) VALUES ('seg', 'Segmentation', 'mIoU · Dice') ON CONFLICT (code) DO NOTHING;
INSERT INTO task_step (task_type_id, position, text) SELECT id, 1, 'Collect images and define mask classes' FROM task_type WHERE code = 'seg' ON CONFLICT DO NOTHING;
INSERT INTO task_step (task_type_id, position, text) SELECT id, 2, 'Annotate polygons or masks (bootstrap with SAM to save time)' FROM task_type WHERE code = 'seg' ON CONFLICT DO NOTHING;
INSERT INTO task_step (task_type_id, position, text) SELECT id, 3, 'Train U-Net, SegFormer or YOLO-seg' FROM task_type WHERE code = 'seg' ON CONFLICT DO NOTHING;
INSERT INTO task_step (task_type_id, position, text) SELECT id, 4, 'Evaluate mIoU and Dice per class' FROM task_type WHERE code = 'seg' ON CONFLICT DO NOTHING;
INSERT INTO task_step (task_type_id, position, text) SELECT id, 5, 'Turn masks into measurements, areas or GIS polygons' FROM task_type WHERE code = 'seg' ON CONFLICT DO NOTHING;
INSERT INTO task_type (code, name, metric) VALUES ('cls', 'Classification', 'Macro-F1 · AUC') ON CONFLICT (code) DO NOTHING;
INSERT INTO task_step (task_type_id, position, text) SELECT id, 1, 'Gather labeled images for each class' FROM task_type WHERE code = 'cls' ON CONFLICT DO NOTHING;
