INSERT INTO task_step (task_type_id, position, text) SELECT id, 4, 'Evaluate F1, AUC and the confusion matrix' FROM task_type WHERE code = 'cls' ON CONFLICT DO NOTHING;
INSERT INTO task_step (task_type_id, position, text) SELECT id, 5, 'Add Grad-CAM to check what the model attends to' FROM task_type WHERE code = 'cls' ON CONFLICT DO NOTHING;
INSERT INTO task_type (code, name, metric) VALUES ('ocr', 'OCR & documents', 'CER · WER') ON CONFLICT (code) DO NOTHING;
