INSERT INTO project (id, title, slug, description, domain_id, task_type_id, level, is_pick, pick_reason, caution, lab) SELECT 1, 'Real-Time Object Detection', 'real-time-object-detection', 'Detect people, cars, animals, and everyday objects using YOLO.', d.id, t.id, 1, FALSE, NULL, NULL, '{"pipeline": "detect", "support": "ready", "params": {}, "samples": {"media": ["bus.jpg"]}, "alternatives": ["segment", "track_count"], "note": null}'::jsonb FROM domain d, task_type t WHERE d.code = 'A' AND t.code = 'det' ON CONFLICT (id) DO NOTHING;
